const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const payload = $json.body ?? $json;
const issue = payload.issue || {};
const title = issue.title || 'Untitled issue';
const body = issue.body || '';
const labels = Array.isArray(issue.labels) ? issue.labels.map((label) => label.name || label) : [];
const normalized = `${title}\n${body}`.toLowerCase();
const severity = /crash|data loss|security/.test(normalized) ? 'high' : /broken|fails|error/.test(normalized) ? 'medium' : 'low';
const owner = /audio|speech|whisper|recitation/.test(normalized) ? 'speech-evaluation' : /ui|layout|screen|design/.test(normalized) ? 'interface-and-design' : 'fullstack-engineering';
const summary = body.trim().slice(0, 400) || 'No issue body provided.';
const descriptionHtml = [
  `<p>${summary.replace(/[<&>]/g, (char) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[char]))}</p>`,
  '<h3>Repo Metadata</h3>',
  `<ul><li><strong>Source:</strong> <a href="${issue.html_url || '#'}">GitHub Issue #${issue.number || 'unknown'}</a></li><li><strong>Suggested Owner:</strong> <code>${owner}</code></li></ul>`,
  '<h3>Labels</h3>',
  `<ul>${labels.map((label) => `<li><code>${label}</code></li>`).join('')}</ul>`,
].join('');

let planeResult = null;
if ($env.PLANE_API_KEY) {
  const response = await fetch(`${$env.PLANE_API_BASE_URL}/api/v1/workspaces/${$env.PLANE_WORKSPACE_SLUG}/projects/${$env.PLANE_PROJECT_ID}/work-items/`, {
    method: 'POST',
    headers: {
      'X-API-Key': $env.PLANE_API_KEY,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      name: `[Issue] ${title}`,
      description_html: descriptionHtml,
      priority: severity,
    }),
  });
  planeResult = { ok: response.ok, status: response.status, body: await response.text() };
}

const reportRelativePath = `issue-triage/${new Date().toISOString().replace(/[:]/g, '-')}-issue-${issue.number || 'unknown'}.md`;
const reportContent = [
  '# GitHub Issue Triage',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Issue: #${issue.number || 'unknown'} ${title}`,
  `Severity: ${severity}`,
  `Suggested Owner: ${owner}`,
  '',
  '## Labels',
  '',
  ...(labels.length ? labels.map((label) => `- ${label}`) : ['- None']),
  '',
  '## Plane Result',
  '',
  planeResult ? '```json\n' + JSON.stringify(planeResult, null, 2) + '\n```' : 'Plane write skipped.',
].join('\n');

const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);

return [{ json: { issueNumber: issue.number, severity, owner, planeResult, reportRelativePath } }];
